-- GenDB engine variant Q11-wrapped_tables: template q11.sql, kind wrapped_tables (generated by generate.py; frozen)
SELECT
  ps_partkey,
  SUM(ps_supplycost * ps_availqty) AS value
FROM (
  SELECT
    *
  FROM partsupp
) AS partsupp, (
  SELECT
    *
  FROM supplier
) AS supplier, (
  SELECT
    *
  FROM nation
) AS nation
WHERE
  ps_suppkey = s_suppkey AND s_nationkey = n_nationkey AND n_name = $1
GROUP BY
  ps_partkey
HAVING
  SUM(ps_supplycost * ps_availqty) > (
    SELECT
      SUM(ps_supplycost * ps_availqty) * $2
    FROM (
      SELECT
        *
      FROM partsupp
    ) AS partsupp, (
      SELECT
        *
      FROM supplier
    ) AS supplier, (
      SELECT
        *
      FROM nation
    ) AS nation
    WHERE
      ps_suppkey = s_suppkey AND s_nationkey = n_nationkey AND n_name = $1
  )
ORDER BY
  value DESC
